"use client";

// morse-404 · 404lab
// Requires ./chrome.tsx and the 404lab tokens.

import { useEffect, useRef, useState } from "react";
import { useInView, useReducedMotion } from "motion/react";
import { Caption, Foot, Screen } from "./chrome";

/* ---------------------------------- morse ---------------------------------- */

const UNIT = 115;
const GROUPS = ["....-", "-----", "....-"];
const DIGITS = ["4", "0", "4"];

type Ev = { on: boolean; dur: number; reveal?: string };

const EVENTS: Ev[] = (() => {
  const out: Ev[] = [];
  GROUPS.forEach((code, gi) => {
    code.split("").forEach((sym) => {
      out.push({ on: true, dur: (sym === "-" ? 3 : 1) * UNIT });
      out.push({ on: false, dur: UNIT });
    });
    out.push({ on: false, dur: 3 * UNIT, reveal: DIGITS[gi] });
  });
  return out;
})();

export function MorseDemo() {
  const reduce = useReducedMotion();
  const ref = useRef<HTMLDivElement>(null);
  const inView = useInView(ref, { margin: "-30px" });
  const [step, setStep] = useState(-1);
  const [text, setText] = useState("");

  useEffect(() => {
    if (inView) setStep(0);
  }, [inView]);

  useEffect(() => {
    if (step < 0) return;
    const ev = EVENTS[step];
    if (!ev) {
      setStep(-1);
      return;
    }
    if (reduce) {
      setText("404");
      setStep(-1);
      return;
    }
    const t = setTimeout(() => {
      if (ev.reveal) setText((s) => s + ev.reveal);
      setStep((s) => s + 1);
    }, ev.dur);
    return () => clearTimeout(t);
  }, [step, reduce]);

  const lit = step >= 0 && EVENTS[step]?.on === true;

  function replay() {
    if (reduce) return;
    setText("");
    setStep(0);
  }

  return (
    <Screen ref={ref} onPointerEnter={replay} onClick={replay} className="bg-[#07080a]">
      <div className="absolute inset-0 bg-[radial-gradient(ellipse_at_center,rgba(233,184,113,0.05),transparent_65%)]" />

      <div className="absolute inset-0 flex flex-col items-center justify-center gap-4">
        <div className="relative grid size-[52px] place-items-center">
          <span className="absolute inset-0 rounded-full border border-line-2" />
          <span
            className={`size-3 rounded-full transition-[background-color,box-shadow] duration-75 ${
              lit
                ? "bg-amber shadow-[0_0_26px_6px_rgba(233,184,113,0.45)]"
                : "bg-fg/20 shadow-[0_0_10px_rgba(233,184,113,0.08)]"
            }`}
          />
          <span className="absolute -bottom-4 lab-mono text-[8px] text-white/35">
            lamp
          </span>
        </div>

        <div className="flex items-baseline gap-2">
          {DIGITS.map((d, i) => (
            <span
              key={i}
              className={`display text-[56px] leading-none transition-colors duration-200 ${
                text.length > i ? "text-fg" : "text-fg/15"
              }`}
            >
              {d}
            </span>
          ))}
        </div>

        <div className="flex items-center gap-3">
          {GROUPS.map((g, gi) => (
            <span
              key={gi}
              className={`lab-mono text-[12px] tracking-[0.18em] ${
                text.length > gi ? "text-amber/80" : "text-white/30"
              }`}
            >
              {g}
            </span>
          ))}
        </div>
      </div>

      <div className="absolute bottom-9 left-4 lab-mono text-[9.5px] text-white/40">
        5 wpm · 404
      </div>

      <Caption label="404 / morse" />
      <Foot method="signal · 115ms" />
    </Screen>
  );
}

"use client";

import Image from "next/image";
import { motion, useReducedMotion } from "motion/react";
import { useState } from "react";
import { ArrowUpRight, Check, Copy } from "lucide-react";

export const EASE = [0.22, 1, 0.36, 1] as const;

/* Every card shares the same framing so the grid reads as one set. */

export function Caption({
  label,
  className = "",
}: {
  label: string;
  className?: string;
}) {
  return (
    <span
      className={`pointer-events-none absolute left-4 top-3 z-20 lab-mono text-[10px] tracking-[0.02em] text-white/75 [text-shadow:0_1px_3px_rgba(8,9,10,0.6)] ${className}`}
    >
      {label}
    </span>
  );
}

export function HomeLink({ label = "back home" }: { label?: string }) {
  return (
    <span className="pointer-events-none inline-flex items-center gap-1 lab-mono text-[10px] text-white/70">
      {label}
      <ArrowUpRight className="size-3" strokeWidth={1.5} />
    </span>
  );
}

export function Foot({
  method,
  label,
}: {
  method: string;
  label?: string;
}) {
  return (
    <div className="pointer-events-none absolute inset-x-0 bottom-0 z-20 flex items-center justify-between px-4 pb-3">
      <HomeLink label={label} />
      <span className="lab-mono text-[10px] text-white/50">{method}</span>
    </div>
  );
}

const SCREEN =
  "group @container relative h-full w-full overflow-hidden bg-ink-900";

export function Screen({
  className = "",
  children,
  ...rest
}: React.ComponentProps<"div">) {
  return (
    <div {...rest} className={`${SCREEN} ${className}`}>
      {children}
    </div>
  );
}

export function ScreenButton({
  className = "",
  children,
  ...rest
}: React.ComponentProps<"button">) {
  return (
    <button
      type="button"
      {...rest}
      className={`${SCREEN} cursor-default text-left ${className}`}
    >
      {children}
    </button>
  );
}

export function Plate({
  src,
  className = "",
  sizes = "(max-width: 768px) 100vw, 33vw",
  opacity,
  position = "center",
}: {
  src: string;
  className?: string;
  sizes?: string;
  opacity?: number;
  position?: string;
}) {
  return (
    <Image
      src={src}
      alt=""
      fill
      sizes={sizes}
      className={`object-cover ${className}`}
      style={{ opacity, objectPosition: position }}
    />
  );
}

/* --------------------------------- helpers -------------------------------- */

export function useReplay() {
  const [run, setRun] = useState(0);
  return { run, replay: () => setRun((n) => n + 1) };
}

export function useStill() {
  return useReducedMotion() ?? false;
}

export const clamp = (v: number, min: number, max: number) =>
  Math.max(min, Math.min(max, v));

/* ------------------------------- install bits ------------------------------ */

export function CopyCommand({
  command,
  className = "",
}: {
  command: string;
  className?: string;
}) {
  const [done, setDone] = useState(false);

  async function copy() {
    try {
      await navigator.clipboard.writeText(command);
      setDone(true);
      setTimeout(() => setDone(false), 1600);
    } catch {
      setDone(false);
    }
  }

  return (
    <button
      type="button"
      onClick={copy}
      aria-label={`Copy ${command}`}
      className={`group/copy flex w-full items-center justify-between gap-4 rounded-control border border-line bg-ink-900 px-3 py-2.5 text-left transition-colors duration-200 hover:border-line-2 active:translate-y-px ${className}`}
    >
      <code className="min-w-0 break-all lab-mono text-[10px] text-fg-2 sm:truncate lg:text-[12px]">
        <span className="mr-1.5 text-amber/80">$</span>
        {command}
      </code>
      <span className="shrink-0 text-fg-3 transition-colors duration-200 group-hover/copy:text-fg">
        {done ? (
          <Check className="size-4" strokeWidth={1.5} />
        ) : (
          <Copy className="size-4" strokeWidth={1.5} />
        )}
      </span>
    </button>
  );
}

export function Reveal({
  children,
  delay = 0,
  className = "",
}: {
  children: React.ReactNode;
  delay?: number;
  className?: string;
}) {
  const reduce = useReducedMotion();
  return (
    <motion.div
      className={className}
      initial={reduce ? false : { opacity: 0, y: 10 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true, margin: "-60px" }}
      transition={{ duration: 0.55, ease: EASE, delay }}
    >
      {children}
    </motion.div>
  );
}
